#include "LedController.h"

// Definindo os pinos para os LEDs
const int ledPins[] = {2, 3, 4, 5, 6, 7, 8}; // Pinos dos LEDs
const int numLeds = sizeof(ledPins) / sizeof(ledPins[0]); // Número de LEDs

LedController ledController(ledPins, numLeds);

void setup() {
  ledController.setup();
}

void loop() {
  ledController.run();
}

#ifndef LedController_h
#define LedController_h

class LedController {
  public:
    LedController(int pins[], int numLeds);
    void setup();
    void run();

  private:
    int* ledPins;
    int numLeds;
    void lightUpLeds();
    void blinkLeds();
};

#endif

#include "Arduino.h"
#include "LedController.h"

LedController::LedController(int pins[], int numLeds) {
  this->ledPins = pins;
  this->numLeds = numLeds;
}

void LedController::setup() {
  for (int i = 0; i < numLeds; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
}

void LedController::run() {
  lightUpLeds();
  blinkLeds();
}

void LedController::lightUpLeds() {
  for (int i = 0; i < numLeds; i++) {
    digitalWrite(ledPins[i], HIGH);
    delay(300);
  }
}

void LedController::blinkLeds() {
  for (int i = 0; i < numLeds; i++) {
    digitalWrite(ledPins[i], HIGH);
  }
  delay(500);
  for (int i = 0; i < numLeds; i++) {
    digitalWrite(ledPins[i], LOW);
  }
  delay(500);
}
